import { DEFAULT_CONTEXT_BUDGET, clipList, clipText } from '../context/budget.js';
export function workerHandoffText(h, maxChars = DEFAULT_CONTEXT_BUDGET.max_handoff_chars) { return clipText(['HHC WORKER HANDOFF', 'Control plane: HHC. Do not become a top-level orchestrator.', `OBJECTIVE: ${clipText(h.objective, 4000)}`, `SCOPE: ${clipList(h.scope, 3000).join(', ') || 'bounded by objective'}`, `CONSTRAINTS: ${clipList(h.constraints, 4000).join(' | ') || 'minimum sufficient change'}`, `REQUIRED EVIDENCE: ${clipList(h.required_evidence, 3000).join(' | ') || 'none'}`, `RELEVANT CONTEXT: ${clipList(h.relevant_context, 5000).join(' | ') || 'none'}`, `SKILLS: ${h.skills.slice(0, 3).join(', ') || 'none'}`, h.skills.length ? 'HHC has selected only the listed skills; do not load unrelated skills.' : 'No skill is required by default; use native engineering judgment.', h.approval_gated_skills?.length ? `APPROVAL-GATED SKILLS: ${h.approval_gated_skills.slice(0, 3).join(', ')}. Load these only through OpenCode native skill tool so host permission ask/deny is preserved.` : 'APPROVAL-GATED SKILLS: none.', 'Return compact JSON-compatible result with status, summary, changed_files, scope_expansions, evidence, open_issues, needs_context. For every changed file outside SCOPE, include scope_expansions entry {file, necessary, reason}. Mark necessary=true only when the task cannot be correctly completed without that file; otherwise revert the collateral change before DONE.'].join('\n'), maxChars); }
const STATUS_ALIAS = { DONE: 'DONE', PASS: 'DONE', DONE_WITH_CONCERNS: 'DONE', FIX_REQUIRED: 'FIX_REQUIRED', NEEDS_CONTEXT: 'NEEDS_CONTEXT', USER_ACTION_REQUIRED: 'BLOCKED', BLOCKED: 'BLOCKED', NO_PROGRESS: 'FIX_REQUIRED', FAILED: 'FAILED', FAIL: 'FAILED' };
export function normalizeWorkerResult(raw) { const x = (raw && typeof raw === 'object') ? raw : {}, status = STATUS_ALIAS[String(x.status ?? '').toUpperCase()] ?? 'FAILED'; const open = Array.isArray(x.open_issues) ? x.open_issues.map(String) : []; if (String(x.status ?? '').toUpperCase() === 'USER_ACTION_REQUIRED' && !open.some(v => v.includes('USER_ACTION_REQUIRED')))
    open.unshift('USER_ACTION_REQUIRED'); return { status, summary: typeof x.summary === 'string' ? clipText(x.summary, 4000) : '', changed_files: Array.isArray(x.changed_files) ? x.changed_files.filter(v => typeof v === 'string').map(String).slice(0, 200) : [], scope_expansions: Array.isArray(x.scope_expansions) ? x.scope_expansions.filter(v => !!v && typeof v === 'object').slice(0, 80).map((v) => ({ file: String(v.file ?? ''), reason: clipText(String(v.reason ?? ''), 600), necessary: v.necessary === true })).filter(v => v.file) : [], evidence: Array.isArray(x.evidence) ? x.evidence.filter(v => !!v && typeof v === 'object').slice(0, 40).map((v) => ({ kind: String(v.kind ?? 'worker'), summary: clipText(String(v.summary ?? ''), 1000), scope: Array.isArray(v.scope) ? v.scope.map(String).slice(0, 50) : undefined, pass: typeof v.pass === 'boolean' ? v.pass : undefined, outcome: v.outcome, reason: typeof v.reason === 'string' ? v.reason : undefined })) : [], open_issues: open.slice(0, 30), needs_context: Array.isArray(x.needs_context) ? x.needs_context.map(String).slice(0, 30) : [] }; }
